mapper.select:
SELECT d.id, d.user_id, d.content, d.images, d.like_count, d.comment_count, d.share_count, d.create_time, d.update_time, d.status
FROM tui_dynamic d
INNER JOIN tui_follow f ON d.user_id = f.follow_user_id
WHERE f.user_id = #{userId} AND f.status = 0 AND d.status = 0 AND d.id < #{cursor}
ORDER BY d.id DESC
LIMIT #{limit}

SELECT id, user_id, content, images, like_count, comment_count, share_count, create_time, update_time, status
FROM tui_dynamic
WHERE user_id = #{userId} AND status = 0 AND id < #{cursor}
ORDER BY id DESC
LIMIT #{limit}

SELECT id FROM tui_dynamic
WHERE status = 0 AND create_time < #{beforeTime}
ORDER BY create_time ASC
LIMIT #{limit}
